#ifndef __NATIVE_TREE_EVAL_H__
#define __NATIVE_TREE_EVAL_H__

#include <math.h>

/*
 * Evaluate a PySTreeD-trained decision tree on the given feature vector.
 *
 * `nodes` must be a node array as generated by
 * single_tree_codegen/pystreed_to_c.py (one of the
 * native_nodes_<category>_<pc>[] arrays defined in
 * native_tree_model_{spatial,pointer}.h, fetched via that header's
 * get_native_nodes()) - node 0 is always the tree's root.
 *
 * Returns 0/1 for negative/positive prediction.
 */
static inline float native_eval_tree(const native_tree_node_t *nodes, const float *feat) {
    int node = 0;
    while (nodes[node].feature >= 0) {
        float v = feat[nodes[node].feature];
        int go_left = isnan(v) ? nodes[node].missing_left
                                : (v <= nodes[node].threshold);
        node = go_left ? nodes[node].left : nodes[node].right;
    }
    return nodes[node].leaf_value;
}

#endif // __NATIVE_TREE_EVAL_H__
